package com.northstar.crm.service;

import com.northstar.crm.domain.*; import com.northstar.crm.repo.*; import com.northstar.crm.security.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class ContactService {
 public record ContactInput(String name,String email,String phone,String title,boolean billingContact,boolean portalAccess){}
 private final ContactRepository contacts;private final OrganizationService organizations;private final ActorResolver actors;private final AccessPolicy access;private final AuditService audit;
 public ContactService(ContactRepository c,OrganizationService o,ActorResolver a,AccessPolicy p,AuditService audit){contacts=c;organizations=o;actors=a;access=p;this.audit=audit;}
 @Transactional(readOnly=true) public List<Contact> forOrganization(UUID orgId){organizations.getAuthorized(orgId);return contacts.findByOrganizationIdOrderByName(orgId);}
 /** User sort input is bounded to this whitelist; both selected repository queries remain parameterized. */
 @Transactional(readOnly=true) public List<Contact> search(UUID orgId,String query,String sort){organizations.getAuthorized(orgId);var ids=List.of(orgId);return "email".equals(sort)?contacts.scopedSearchByEmail(ids,query==null?"":query.strip()):contacts.scopedSearchByName(ids,query==null?"":query.strip());}
 @Transactional public Contact create(UUID orgId,ContactInput input){var actor=actors.current();var org=organizations.getAuthorized(orgId);access.requireManageOrganization(actor,org);validate(input);var c=contacts.save(new Contact(orgId,input.name().strip(),input.email().strip(),input.phone(),input.title(),input.billingContact(),input.portalAccess()));audit.record(actor,"CONTACT_CREATED","Contact",c.getId(),"{}","email="+c.getEmail(),"organization owner or admin");return c;}
 @Transactional public Contact update(UUID id,ContactInput input){var actor=actors.current();var c=contacts.findById(id).orElseThrow();var org=organizations.getAuthorized(c.getOrganizationId());access.requireManageOrganization(actor,org);validate(input);c.update(input.name().strip(),input.phone(),input.title(),input.billingContact(),input.portalAccess());audit.record(actor,"CONTACT_UPDATED","Contact",id,"email="+c.getEmail(),"name="+c.getName(),"organization owner or admin");return c;}
 @Transactional public void delete(UUID id){var actor=actors.current();var c=contacts.findById(id).orElseThrow();access.requireManageOrganization(actor,organizations.getAuthorized(c.getOrganizationId()));contacts.delete(c);audit.record(actor,"CONTACT_DELETED","Contact",id,"email="+c.getEmail(),"{}","organization owner or admin");}
 private void validate(ContactInput i){if(i.name()==null||i.name().isBlank())throw new IllegalArgumentException("Name required");if(i.email()==null||!i.email().matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$"))throw new IllegalArgumentException("Valid email required");if(i.phone()!=null&&i.phone().length()>40)throw new IllegalArgumentException("Phone too long");}
 /** Issue the portal access code a customer contact uses to open shared documents. */
 @Transactional public void setPortalCode(UUID contactId,String code){var actor=actors.current();var c=contacts.findById(contactId).orElseThrow();var org=organizations.getAuthorized(c.getOrganizationId());access.requireManageOrganization(actor,org);if(code==null||code.length()<6||code.length()>128)throw new IllegalArgumentException("Access code must be 6-128 characters");c.setPortalCodeHash(portalDigest(code));audit.record(actor,"PORTAL_CODE_SET","Contact",contactId,"{}","access code updated","organization owner or admin");}
 @Transactional(readOnly=true) public boolean verifyPortalCode(String email,String code){var c=contacts.findFirstByEmailIgnoreCase(Optional.ofNullable(email).orElse("")).orElseThrow(()->new IllegalArgumentException("No portal contact is registered for that email"));if(c.getPortalCodeHash()==null)throw new IllegalArgumentException("No portal access code is set for this contact");if(code==null)return false;return java.security.MessageDigest.isEqual(portalDigest(code).getBytes(java.nio.charset.StandardCharsets.US_ASCII),c.getPortalCodeHash().getBytes(java.nio.charset.StandardCharsets.US_ASCII));}
 private String portalDigest(String code){return org.springframework.util.DigestUtils.md5DigestAsHex(code.getBytes(java.nio.charset.StandardCharsets.UTF_8));}
}
